def enclosed(I):
    from collections import deque
    R,C=I.shape
    reach=np.zeros_like(I,bool)
    dq=deque()
    for i in range(R):
        for j in [0,C-1]:
            if I[i,j]==0 and not reach[i,j]: reach[i,j]=True; dq.append((i,j))
    for j in range(C):
        for i in [0,R-1]:
            if I[i,j]==0 and not reach[i,j]: reach[i,j]=True; dq.append((i,j))
    while dq:
        r,c=dq.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<R and 0<=nc<C and I[nr,nc]==0 and not reach[nr,nc]:
                reach[nr,nc]=True; dq.append((nr,nc))
    return [(r,c) for r in range(R) for c in range(C) if I[r,c]==0 and not reach[r,c]]
